package dev.raf.radar;
import java.io.*;import java.util.*;import java.util.function.LongSupplier;import org.json.*;
/** Persistent samples, scoped to account and fixed source point; no GPS tracks or names. */
final class ObservationQueue {
 final File file;final LongSupplier clock;JSONArray rows=new JSONArray();JSONObject captured=new JSONObject();
 ObservationQueue(File file,LongSupplier clock){this.file=file;this.clock=clock;try{JSONObject data=new JSONObject(DiagnosticJournal.read(file));rows=data.getJSONArray("rows");captured=data.getJSONObject("captured");}catch(Exception ignored){}prune();}
 synchronized boolean capture(int owner,Point p,List<Store.Reading> readings,String version,String timezone){if(owner<1||p.dynamic||!p.enabled)return false;for(Store.Reading reading:readings){long now=clock.getAsLong();if(!"econom".equals(reading.tariff)||reading.rub==null||reading.rub<0||reading.time<=0||now-reading.time>180000||reading.time>now+60000)continue;String key=owner+":"+p.id;long before=captured.optLong(key,0);if(before>0&&reading.time-before<300000)return false;try{JSONObject sample=new JSONObject().put("owner",owner).put("observationId",UUID.randomUUID().toString()).put("sourcePoint",p.id).put("lat",p.lat).put("lon",p.lon).put("measuredAt",reading.time).put("rub",reading.rub).put("tariff","econom").put("version",version).put("timezone",timezone);rows.put(sample);captured.put(key,reading.time);prune();save();return true;}catch(Exception e){return false;}}return false;}
 synchronized void prune(){JSONArray kept=new JSONArray();long now=clock.getAsLong();for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&r.optLong("measuredAt",0)>=now-7L*86400000&&r.optLong("measuredAt",0)<=now+60000)kept.put(r);}rows=kept;while(rows.length()>5000||rows.toString().length()>2000000)rows.remove(0);if(captured.length()>2000){JSONObject recent=new JSONObject();Iterator<String> keys=captured.keys();while(keys.hasNext()){String key=keys.next();try{if(now-captured.optLong(key,0)<7L*86400000)recent.put(key,captured.optLong(key));}catch(Exception ignored){}}captured=recent;}}
 synchronized JSONArray batch(int owner){prune();JSONArray result=new JSONArray();for(int i=0;i<rows.length()&&result.length()<20;i++){JSONObject row=rows.optJSONObject(i);if(row!=null&&row.optInt("owner")==owner)result.put(row);}return result;}
 synchronized void acknowledge(JSONArray ids)throws Exception{Set<String> done=new HashSet<>();for(int i=0;i<ids.length();i++)done.add(ids.getString(i));JSONArray kept=new JSONArray();for(int i=0;i<rows.length();i++)if(!done.contains(rows.getJSONObject(i).optString("observationId")))kept.put(rows.getJSONObject(i));rows=kept;save();}
 void save()throws Exception{file.getParentFile().mkdirs();DiagnosticJournal.write(file,new JSONObject().put("rows",rows).put("captured",captured).toString());}
}
